import sys
import bisect

def min_cost(n, k, a, b):
    def can_prepare_and_print(threshold):
        count = 0
        prepared_days = []
        for i in range(n):
            if a[i] <= threshold:
                prepared_days.append(i)
        for i in range(n):
            if b[i] <= threshold:
                idx = bisect.bisect_left(prepared_days, i)
                if idx < len(prepared_days):
                    count += 1
                    prepared_days.pop(idx)
        return count >= k

    low = 0
    high = 10**18
    while low < high:
        mid = (low + high) // 2
        if can_prepare_and_print(mid):
            high = mid
        else:
            low = mid + 1
    return low

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:n+2]))
    b = list(map(int, data[n+2:2*n+2]))

    result = min_cost(n, k, a, b)
    print(result)
